static const char *const kPyBlock000[] = {
    "# min-heap backed by a flat list with sift up and down",
    "",
    "class BinaryHeap:",
    "    def __init__(self) -> None:",
    "        self.data: list[int] = []",
    "",
    "    def _parent(self, i: int) -> int:",
    "        return (i - 1) // 2",
    "",
    "    def _sift_up(self, i: int) -> None:",
    "        while i > 0 and self.data[self._parent(i)] > self.data[i]:",
    "            p = self._parent(i)",
    "            self.data[i], self.data[p] = self.data[p], self.data[i]",
    "            i = p",
    "",
    "    def _sift_down(self, i: int) -> None:",
    "        n = len(self.data)",
    "        while True:",
    "            left = 2 * i + 1",
    "            right = 2 * i + 2",
    "            smallest = i",
    "            if left < n and self.data[left] < self.data[smallest]:",
    "                smallest = left",
    "            if right < n and self.data[right] < self.data[smallest]:",
    "                smallest = right",
    "            if smallest == i:",
    "                return",
    "            self.data[i], self.data[smallest] = (",
    "                self.data[smallest], self.data[i])",
    "            i = smallest",
    "",
    "    def push(self, value: int) -> None:",
    "        self.data.append(value)",
    "        self._sift_up(len(self.data) - 1)",
    "",
    "    def pop(self) -> int:",
    "        top = self.data[0]",
    "        last = self.data.pop()",
    "        if self.data:",
    "            self.data[0] = last",
    "            self._sift_down(0)",
    "        return top",
    "",
};

