static const char *const kRsBlock136[] = {
    "// burrows-wheeler transform via rotation sorting",
    "fn rot_cmp(bytes: &Vec<u8>, x: usize, y: usize) -> i32 {",
    "    let n = bytes.len();",
    "    for k in 0..n {",
    "        let bx = bytes[(x + k) % n];",
    "        let by = bytes[(y + k) % n];",
    "        if bx < by {",
    "            return -1;",
    "        }",
    "        if bx > by {",
    "            return 1;",
    "        }",
    "    }",
    "    0",
    "}",
    "",
    "fn bwt_transform(input: &String) -> (String, usize) {",
    "    let bytes: Vec<u8> = input.bytes().collect();",
    "    let n = bytes.len();",
    "    if n == 0 {",
    "        return (String::new(), 0);",
    "    }",
    "    let mut rows: Vec<usize> = (0..n).collect();",
    "    rows.sort_by(|&x, &y| rot_cmp(&bytes, x, y).cmp(&0));",
    "    let mut last = String::new();",
    "    let mut primary = 0;",
    "    for (row, &start) in rows.iter().enumerate() {",
    "        let idx = (start + n - 1) % n;",
    "        last.push(bytes[idx] as char);",
    "        if start == 0 {",
    "            primary = row;",
    "        }",
    "    }",
    "    (last, primary)",
    "}",
    "",
};

static const char *const kRsBlock137[] = {
    "// simple tokenizer splitting text into typed tokens",
    "enum Token {",
    "    Word(String),",
    "    Number(String),",
    "    Symbol(String),",
    "}",
    "",
    "fn tokenize(source: &String) -> Vec<Token> {",
    "    let bytes: Vec<u8> = source.bytes().collect();",
    "    let mut tokens = Vec::new();",
    "    let mut i = 0;",
    "    while i < bytes.len() {",
    "        let b = bytes[i];",
    "        if b.is_ascii_whitespace() {",
    "            i += 1;",
    "        } else if b.is_ascii_alphabetic() {",
    "            let mut word = String::new();",
    "            while i < bytes.len()",
    "                && bytes[i].is_ascii_alphabetic() {",
    "                word.push(bytes[i] as char);",
    "                i += 1;",
    "            }",
    "            tokens.push(Token::Word(word));",
    "        } else if b.is_ascii_digit() {",
    "            let mut num = String::new();",
    "            while i < bytes.len()",
    "                && bytes[i].is_ascii_digit() {",
    "                num.push(bytes[i] as char);",
    "                i += 1;",
    "            }",
    "            tokens.push(Token::Number(num));",
    "        } else {",
    "            let mut sym = String::new();",
    "            sym.push(b as char);",
    "            tokens.push(Token::Symbol(sym));",
    "            i += 1;",
    "        }",
    "    }",
    "    tokens",
    "}",
    "",
};

static const char *const kRsBlock138[] = {
    "// soundex phonetic encoder producing a 4-char code",
    "fn up(b: u8) -> u8 { if b >= 97 && b <= 122 { b - 32 } else { b } }",
    "",
    "fn soundex_digit(b: u8) -> u8 {",
    "    match b {",
    "        66 | 70 | 80 | 86 => 1,",
    "        67 | 71 | 74 | 75 | 81 | 83 | 88 | 90 => 2,",
    "        68 | 84 => 3,",
    "        76 => 4,",
    "        77 | 78 => 5,",
    "        82 => 6,",
    "        _ => 0,",
    "    }",
    "}",
    "",
    "fn soundex(name: &String) -> String {",
    "    let bytes: Vec<u8> = name.bytes().collect();",
    "    if bytes.is_empty() {",
    "        return String::from(\"0000\");",
    "    }",
    "    let first = up(bytes[0]);",
    "    let mut code = String::new();",
    "    code.push(first as char);",
    "    let mut prev = soundex_digit(first);",
    "    for k in 1..bytes.len() {",
    "        let d = soundex_digit(up(bytes[k]));",
    "        if d != 0 && d != prev {",
    "            code.push((d + 48) as char);",
    "        }",
    "        prev = d;",
    "    }",
    "    while code.len() < 4 {",
    "        code.push(48u8 as char);",
    "    }",
    "    code.truncate(4);",
    "    code",
    "}",
    "",
};

static const char *const kRsBlock139[] = {
    "// hamming distance for equal-length byte sequences",
    "fn hamming_bytes(a: &String, b: &String) -> Option<usize> {",
    "    let ba: Vec<u8> = a.bytes().collect();",
    "    let bb: Vec<u8> = b.bytes().collect();",
    "    if ba.len() != bb.len() {",
    "        return None;",
    "    }",
    "    let mut count = 0;",
    "    for i in 0..ba.len() {",
    "        if ba[i] != bb[i] {",
    "            count += 1;",
    "        }",
    "    }",
    "    Some(count)",
    "}",
    "",
    "// hamming weight between two unsigned integers",
    "fn hamming_bits(a: u64, b: u64) -> u32 {",
    "    let mut diff = a ^ b;",
    "    let mut count = 0;",
    "    while diff != 0 {",
    "        count += (diff & 1) as u32;",
    "        diff >>= 1;",
    "    }",
    "    count",
    "}",
    "",
    "fn hamming_popcount(a: u64, b: u64) -> u32 {",
    "    (a ^ b).count_ones()",
    "}",
    "",
};

