static const char *const kPgBlock013[] = {
    "",
    "CREATE TABLE audit_log (",
    "    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,",
    "    table_name  TEXT NOT NULL,",
    "    row_pk      TEXT NOT NULL,",
    "    action      TEXT NOT NULL CHECK (action IN ('INSERT', 'UPDATE',",
    "                                                'DELETE')),",
    "    old_row     JSONB,",
    "    new_row     JSONB,",
    "    changed_by  TEXT NOT NULL DEFAULT current_user,",
    "    changed_at  TIMESTAMPTZ NOT NULL DEFAULT now()",
    ");",
    "",
    "CREATE OR REPLACE FUNCTION audit_row_change()",
    "RETURNS trigger AS $$",
    "BEGIN",
    "    IF TG_OP = 'DELETE' THEN",
    "        INSERT INTO audit_log (table_name, row_pk, action, old_row)",
    "        VALUES (TG_TABLE_NAME, OLD.id::TEXT, TG_OP, to_jsonb(OLD));",
    "        RETURN OLD;",
    "    END IF;",
    "",
    "    INSERT INTO audit_log (table_name, row_pk, action, old_row, new_row)",
    "    VALUES (TG_TABLE_NAME,",
    "            NEW.id::TEXT,",
    "            TG_OP,",
    "            CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END,",
    "            to_jsonb(NEW));",
    "    RETURN NEW;",
    "END;",
    "$$ LANGUAGE plpgsql;",
    "",
    "CREATE TRIGGER trg_customers_audit",
    "    AFTER INSERT OR UPDATE OR DELETE ON customers",
    "    FOR EACH ROW EXECUTE FUNCTION audit_row_change();",
    "",
    "-- which columns actually changed in the last hour",
    "SELECT a.row_pk, k AS column_name,",
    "       a.old_row -> k AS before, a.new_row -> k AS after",
    "  FROM audit_log a",
    "  CROSS JOIN LATERAL jsonb_object_keys(a.new_row) AS k",
    " WHERE a.action = 'UPDATE'",
    "   AND a.changed_at >= now() - interval '1 hour'",
    "   AND a.old_row -> k IS DISTINCT FROM a.new_row -> k;",
    "",
};
