static const char *const kPgBlock045[] = {
    "",
    "-- keep a rolling window of monthly partitions for the events table;",
    "-- scheduled daily, safe to run repeatedly",
    "DO $$",
    "DECLARE",
    "    v_month  DATE;",
    "    v_name   TEXT;",
    "BEGIN",
    "    FOR v_month IN",
    "        SELECT generate_series(",
    "                   date_trunc('month', now())::DATE,",
    "                   (date_trunc('month', now()) + interval '3 months')::DATE,",
    "                   interval '1 month'",
    "               )::DATE",
    "    LOOP",
    "        v_name := format('events_%s', to_char(v_month, 'YYYY_MM'));",
    "",
    "        IF to_regclass(v_name) IS NULL THEN",
    "            EXECUTE format(",
    "                'CREATE TABLE %I PARTITION OF events",
    "                     FOR VALUES FROM (%L) TO (%L)',",
    "                v_name,",
    "                v_month,",
    "                (v_month + interval '1 month')::DATE",
    "            );",
    "            RAISE NOTICE 'created partition %', v_name;",
    "        END IF;",
    "    END LOOP;",
    "",
    "    -- detach anything older than 13 months so it can be archived",
    "    FOR v_name IN",
    "        SELECT c.relname",
    "          FROM pg_inherits i",
    "          JOIN pg_class c ON c.oid = i.inhrelid",
    "          JOIN pg_class p ON p.oid = i.inhparent",
    "         WHERE p.relname = 'events'",
    "           AND c.relname < format('events_%s',",
    "                   to_char(now() - interval '13 months', 'YYYY_MM'))",
    "    LOOP",
    "        EXECUTE format('ALTER TABLE events DETACH PARTITION %I', v_name);",
    "    END LOOP;",
    "END;",
    "$$;",
    "",
};
