static const char *const kPgBlock051[] = {
    "",
    "CREATE TABLE movie_ratings (",
    "    user_id      BIGINT NOT NULL,",
    "    movie_id     BIGINT NOT NULL,",
    "    stars        SMALLINT NOT NULL CHECK (stars BETWEEN 1 AND 5),",
    "    rated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),",
    "    PRIMARY KEY (user_id, movie_id)",
    ");",
    "",
    "-- bayesian average so a film with three 5-star votes does not top",
    "-- the chart above one with ten thousand 4.6 votes",
    "WITH per_movie AS (",
    "    SELECT movie_id, COUNT(*) AS votes, AVG(stars)::NUMERIC AS avg_stars",
    "      FROM movie_ratings",
    "     GROUP BY movie_id",
    "),",
    "global AS (",
    "    SELECT SUM(votes * avg_stars) / SUM(votes) AS c,",
    "           percentile_cont(0.5) WITHIN GROUP (ORDER BY votes)::NUMERIC",
    "               AS m",
    "      FROM per_movie",
    ")",
    "SELECT m.title,",
    "       p.votes,",
    "       ROUND(p.avg_stars, 2) AS raw_avg,",
    "       ROUND((p.votes * p.avg_stars + g.m * g.c) / (p.votes + g.m), 3)",
    "           AS weighted",
    "  FROM per_movie p",
    "  JOIN movies m ON m.id = p.movie_id",
    " CROSS JOIN global g",
    " ORDER BY weighted DESC",
    " LIMIT 20;",
    "",
    "-- star distribution for one film, as a jsonb histogram",
    "SELECT jsonb_object_agg(stars, n ORDER BY stars) AS histogram",
    "  FROM (SELECT stars, COUNT(*) AS n",
    "          FROM movie_ratings",
    "         WHERE movie_id = 603",
    "         GROUP BY stars) h;",
    "",
};
