static const char *const kPgBlock063[] = {
    "",
    "CREATE TABLE player_ratings (",
    "    player_id     BIGINT PRIMARY KEY,",
    "    elo           NUMERIC(7, 2) NOT NULL DEFAULT 1500,",
    "    games         INT NOT NULL DEFAULT 0,",
    "    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()",
    ");",
    "",
    "-- classic Elo update after a single game; score is 1, 0.5 or 0",
    "CREATE OR REPLACE FUNCTION record_game(",
    "    p_white BIGINT, p_black BIGINT, p_white_score NUMERIC",
    ") RETURNS TABLE (player_id BIGINT, new_elo NUMERIC) AS $$",
    "DECLARE",
    "    v_w      NUMERIC;",
    "    v_b      NUMERIC;",
    "    v_expect NUMERIC;",
    "    v_k      CONSTANT NUMERIC := 24;",
    "BEGIN",
    "    IF p_white_score NOT IN (0, 0.5, 1) THEN",
    "        RAISE EXCEPTION 'invalid score %', p_white_score;",
    "    END IF;",
    "",
    "    SELECT elo INTO v_w FROM player_ratings pr",
    "     WHERE pr.player_id = p_white FOR UPDATE;",
    "    SELECT elo INTO v_b FROM player_ratings pr",
    "     WHERE pr.player_id = p_black FOR UPDATE;",
    "",
    "    v_expect := 1 / (1 + power(10, (v_b - v_w) / 400));",
    "",
    "    UPDATE player_ratings pr",
    "       SET elo = pr.elo + v_k * (p_white_score - v_expect),",
    "           games = pr.games + 1, updated_at = now()",
    "     WHERE pr.player_id = p_white;",
    "",
    "    UPDATE player_ratings pr",
    "       SET elo = pr.elo + v_k * ((1 - p_white_score) - (1 - v_expect)),",
    "           games = pr.games + 1, updated_at = now()",
    "     WHERE pr.player_id = p_black;",
    "",
    "    RETURN QUERY",
    "        SELECT pr.player_id, pr.elo",
    "          FROM player_ratings pr",
    "         WHERE pr.player_id IN (p_white, p_black);",
    "END;",
    "$$ LANGUAGE plpgsql;",
    "",
    "SELECT * FROM record_game(101, 202, 0.5);",
    "",
};
