static const char *const kPgBlock084[] = {
    "",
    "CREATE TABLE election_results (",
    "    district      TEXT NOT NULL,",
    "    party         TEXT NOT NULL,",
    "    votes         INT NOT NULL CHECK (votes >= 0),",
    "    PRIMARY KEY (district, party)",
    ");",
    "",
    "CREATE TABLE district_seats (",
    "    district      TEXT PRIMARY KEY,",
    "    seats         SMALLINT NOT NULL CHECK (seats > 0)",
    ");",
    "",
    "-- D Hondt allocation: divide each party total by 1..seats, take the",
    "-- largest quotients per district",
    "WITH quotients AS (",
    "    SELECT r.district,",
    "           r.party,",
    "           r.votes::NUMERIC / d AS q",
    "      FROM election_results r",
    "      JOIN district_seats s USING (district)",
    "     CROSS JOIN LATERAL generate_series(1, s.seats) AS d",
    "),",
    "ranked AS (",
    "    SELECT q.*,",
    "           ROW_NUMBER() OVER (PARTITION BY district ORDER BY q DESC)",
    "               AS pos",
    "      FROM quotients q",
    ")",
    "SELECT r.district, r.party, COUNT(*) AS seats_won",
    "  FROM ranked r",
    "  JOIN district_seats s USING (district)",
    " WHERE r.pos <= s.seats",
    " GROUP BY r.district, r.party",
    " ORDER BY r.district, seats_won DESC;",
    "",
    "-- vote share of the winning party in each district",
    "SELECT DISTINCT ON (district)",
    "       district,",
    "       party,",
    "       votes,",
    "       ROUND(100.0 * votes / SUM(votes) OVER (PARTITION BY district), 2)",
    "           AS share_pct",
    "  FROM election_results",
    " ORDER BY district, votes DESC;",
    "",
};
