static const char *const kMyBlock001[] = {
    "",
    "# Daily revenue for the finance dashboard, last 30 days.",
    "SELECT",
    "  DATE_FORMAT(o.placed_at, '%Y-%m-%d') AS day,",
    "  COUNT(*) AS orders_cnt,",
    "  SUM(o.grand_total) AS revenue,",
    "  ROUND(AVG(o.grand_total), 2) AS avg_ticket,",
    "  SUM(IF(o.status = 'refunded', o.grand_total, 0)) AS refunded",
    "FROM `orders` o",
    "WHERE o.placed_at >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)",
    "  AND o.status <> 'cancelled'",
    "GROUP BY day",
    "ORDER BY day DESC;",
    "",
    "-- Same window, split by currency, with a running total per currency.",
    "SELECT",
    "  currency,",
    "  day,",
    "  revenue,",
    "  SUM(revenue) OVER (",
    "    PARTITION BY currency ORDER BY day",
    "    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW",
    "  ) AS running_revenue",
    "FROM (",
    "  SELECT currency,",
    "         DATE(placed_at) AS day,",
    "         SUM(grand_total) AS revenue",
    "  FROM `orders`",
    "  WHERE placed_at >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)",
    "  GROUP BY currency, DATE(placed_at)",
    ") d",
    "ORDER BY currency, day;",
    "",
};
