static const char *const kMyBlock004[] = {
    "",
    "DELIMITER $$",
    "",
    "-- Reserve stock for an order line; fails loudly if not enough on hand.",
    "CREATE PROCEDURE reserve_stock(",
    "  IN p_sku VARCHAR(32),",
    "  IN p_warehouse_id SMALLINT UNSIGNED,",
    "  IN p_qty INT UNSIGNED",
    ")",
    "BEGIN",
    "  DECLARE v_on_hand INT DEFAULT 0;",
    "  DECLARE v_reserved INT DEFAULT 0;",
    "",
    "  START TRANSACTION;",
    "",
    "  SELECT on_hand, reserved",
    "    INTO v_on_hand, v_reserved",
    "  FROM inventory",
    "  WHERE sku = p_sku AND warehouse_id = p_warehouse_id",
    "  FOR UPDATE;",
    "",
    "  IF v_on_hand IS NULL THEN",
    "    ROLLBACK;",
    "    SIGNAL SQLSTATE '45000'",
    "      SET MESSAGE_TEXT = 'Unknown SKU for this warehouse';",
    "  END IF;",
    "",
    "  IF v_on_hand - v_reserved < p_qty THEN",
    "    ROLLBACK;",
    "    SIGNAL SQLSTATE '45000'",
    "      SET MESSAGE_TEXT = 'Insufficient stock to reserve';",
    "  END IF;",
    "",
    "  UPDATE inventory",
    "  SET reserved = reserved + p_qty",
    "  WHERE sku = p_sku AND warehouse_id = p_warehouse_id;",
    "",
    "  COMMIT;",
    "END$$",
    "",
    "DELIMITER ;",
    "",
    "CALL reserve_stock('TEA-OOLONG-250', 3, 12);",
    "",
};
