static const char *const kMyBlock025[] = {
    "",
    "# Campaign performance: impressions vs clicks vs spend.",
    "SELECT",
    "  cp.id,",
    "  cp.name,",
    "  IFNULL(i.impressions, 0) AS impressions,",
    "  IFNULL(k.clicks, 0) AS clicks,",
    "  ROUND(100 * IFNULL(k.clicks, 0) / NULLIF(i.impressions, 0), 3)",
    "    AS ctr_pct,",
    "  ROUND(cp.cpc_bid * IFNULL(k.clicks, 0), 2) AS spend,",
    "  ROUND(cp.cpc_bid * IFNULL(k.clicks, 0)",
    "        / NULLIF(cv.conversions, 0), 2) AS cost_per_conv",
    "FROM campaigns cp",
    "LEFT JOIN (",
    "  SELECT campaign_id, COUNT(*) AS impressions",
    "  FROM ad_impressions",
    "  WHERE served_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)",
    "  GROUP BY campaign_id",
    ") i ON i.campaign_id = cp.id",
    "LEFT JOIN (",
    "  SELECT campaign_id, COUNT(*) AS clicks",
    "  FROM ad_clicks",
    "  WHERE clicked_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)",
    "    AND is_fraud = 0",
    "  GROUP BY campaign_id",
    ") k ON k.campaign_id = cp.id",
    "LEFT JOIN (",
    "  SELECT campaign_id, COUNT(*) AS conversions",
    "  FROM ad_conversions",
    "  WHERE converted_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)",
    "  GROUP BY campaign_id",
    ") cv ON cv.campaign_id = cp.id",
    "WHERE cp.status = 'running'",
    "ORDER BY spend DESC;",
    "",
};
