static const char *const kMyBlock029[] = {
    "",
    "# Monthly recurring revenue by plan, normalized to monthly amounts.",
    "SELECT",
    "  DATE_FORMAT(m.month_start, '%Y-%m') AS month,",
    "  s.plan_code,",
    "  COUNT(*) AS active_subs,",
    "  ROUND(SUM(",
    "    IF(s.interval_unit = 'year', p.unit_price / 12, p.unit_price)",
    "    * s.seats",
    "  ), 2) AS mrr",
    "FROM month_starts m",
    "JOIN subscriptions s",
    "  ON s.started_at < m.month_start + INTERVAL 1 MONTH",
    " AND (s.cancelled_at IS NULL OR s.cancelled_at >= m.month_start)",
    " AND s.status <> 'trialing'",
    "JOIN plans p ON p.code = s.plan_code",
    "WHERE m.month_start >= DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'),",
    "                                INTERVAL 11 MONTH)",
    "GROUP BY month, s.plan_code",
    "ORDER BY month, mrr DESC;",
    "",
    "-- Churn: subscriptions cancelled in a month vs active at its start.",
    "SELECT",
    "  DATE_FORMAT(cancelled_at, '%Y-%m') AS month,",
    "  COUNT(*) AS churned,",
    "  ROUND(100 * COUNT(*) / (",
    "    SELECT COUNT(*) FROM subscriptions s2",
    "    WHERE s2.started_at < DATE_FORMAT(s.cancelled_at, '%Y-%m-01')",
    "      AND (s2.cancelled_at IS NULL",
    "           OR s2.cancelled_at >= DATE_FORMAT(s.cancelled_at, '%Y-%m-01'))",
    "  ), 2) AS churn_pct",
    "FROM subscriptions s",
    "WHERE cancelled_at >= CURDATE() - INTERVAL 6 MONTH",
    "GROUP BY month",
    "ORDER BY month;",
    "",
};
static const char *const kMyBlock030[] = {
    "",
    "-- Double-entry ledger. Every journal entry must balance to zero.",
    "CREATE TABLE `ledger_accounts` (",
    "  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,",
    "  `code` VARCHAR(16) NOT NULL,",
    "  `name` VARCHAR(120) NOT NULL,",
    "  `type` ENUM('asset','liability','equity','income','expense') NOT NULL,",
    "  `parent_id` INT UNSIGNED NULL,",
    "  PRIMARY KEY (`id`),",
    "  UNIQUE KEY `uq_accounts_code` (`code`)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;",
    "",
    "CREATE TABLE `journal_lines` (",
    "  `entry_id` BIGINT UNSIGNED NOT NULL,",
    "  `line_no` SMALLINT UNSIGNED NOT NULL,",
    "  `account_id` INT UNSIGNED NOT NULL,",
    "  `amount` DECIMAL(14,2) NOT NULL,",
    "  `memo` VARCHAR(255) NULL,",
    "  `posted_on` DATE NOT NULL,",
    "  PRIMARY KEY (`entry_id`, `line_no`),",
    "  KEY `idx_jl_account_date` (`account_id`, `posted_on`)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;",
    "",
    "-- Any entry that does not sum to zero is a bug upstream.",
    "SELECT entry_id, SUM(amount) AS imbalance, COUNT(*) AS lines",
    "FROM `journal_lines`",
    "GROUP BY entry_id",
    "HAVING SUM(amount) <> 0",
    "ORDER BY ABS(imbalance) DESC",
    "LIMIT 100;",
    "",
    "-- Trial balance as of the end of last month.",
    "SELECT",
    "  a.code,",
    "  a.name,",
    "  a.type,",
    "  SUM(IF(jl.amount > 0, jl.amount, 0)) AS debits,",
    "  SUM(IF(jl.amount < 0, -jl.amount, 0)) AS credits,",
    "  SUM(jl.amount) AS balance",
    "FROM `ledger_accounts` a",
    "JOIN `journal_lines` jl ON jl.account_id = a.id",
    "WHERE jl.posted_on <= LAST_DAY(CURDATE() - INTERVAL 1 MONTH)",
    "GROUP BY a.id, a.code, a.name, a.type",
    "ORDER BY a.code;",
    "",
};
static const char *const kMyBlock031[] = {
    "",
    "DELIMITER $$",
    "",
    "-- Post a simple two-line transfer between accounts.",
    "CREATE PROCEDURE post_transfer(",
    "  IN p_from_code VARCHAR(16),",
    "  IN p_to_code VARCHAR(16),",
    "  IN p_amount DECIMAL(14,2),",
    "  IN p_memo VARCHAR(255)",
    ")",
    "BEGIN",
    "  DECLARE v_from INT UNSIGNED;",
    "  DECLARE v_to INT UNSIGNED;",
    "  DECLARE v_entry BIGINT UNSIGNED;",
    "  DECLARE EXIT HANDLER FOR SQLEXCEPTION",
    "  BEGIN",
    "    ROLLBACK;",
    "    RESIGNAL;",
    "  END;",
    "",
    "  IF p_amount <= 0 THEN",
    "    SIGNAL SQLSTATE '45000'",
    "      SET MESSAGE_TEXT = 'Transfer amount must be positive';",
    "  END IF;",
    "",
    "  SELECT id INTO v_from FROM ledger_accounts WHERE code = p_from_code;",
    "  SELECT id INTO v_to FROM ledger_accounts WHERE code = p_to_code;",
    "",
    "  START TRANSACTION;",
    "",
    "  INSERT INTO journal_entries (created_at, memo) VALUES (NOW(), p_memo);",
    "  SET v_entry = LAST_INSERT_ID();",
    "",
    "  INSERT INTO journal_lines",
    "    (entry_id, line_no, account_id, amount, memo, posted_on)",
    "  VALUES",
    "    (v_entry, 1, v_to, p_amount, p_memo, CURDATE()),",
    "    (v_entry, 2, v_from, -p_amount, p_memo, CURDATE());",
    "",
    "  COMMIT;",
    "END$$",
    "",
    "DELIMITER ;",
    "",
    "CALL post_transfer('1010', '1200', 2500.00, 'move float to reserve');",
    "",
};
