static const char *const kMyBlock039[] = {
    "",
    "-- Cost per kilometre by vehicle over the trailing twelve months.",
    "SELECT",
    "  v.plate,",
    "  CONCAT(v.make, ' ', v.model, ' ', v.model_year) AS vehicle,",
    "  SUM(s.cost) AS service_cost,",
    "  IFNULL(f.fuel_cost, 0) AS fuel_cost,",
    "  MAX(s.odometer_km) - MIN(s.odometer_km) AS km_driven,",
    "  ROUND((SUM(s.cost) + IFNULL(f.fuel_cost, 0))",
    "        / NULLIF(MAX(s.odometer_km) - MIN(s.odometer_km), 0), 3)",
    "    AS cost_per_km",
    "FROM vehicles v",
    "JOIN service_records s ON s.vehicle_id = v.id",
    "LEFT JOIN (",
    "  SELECT vehicle_id, SUM(litres * price_per_litre) AS fuel_cost",
    "  FROM fuel_purchases",
    "  WHERE bought_on >= CURDATE() - INTERVAL 12 MONTH",
    "  GROUP BY vehicle_id",
    ") f ON f.vehicle_id = v.id",
    "WHERE s.serviced_on >= CURDATE() - INTERVAL 12 MONTH",
    "GROUP BY v.id, v.plate, vehicle, f.fuel_cost",
    "ORDER BY cost_per_km DESC;",
    "",
    "-- Retire anything older than 12 model years with high repair spend.",
    "UPDATE vehicles v",
    "JOIN (",
    "  SELECT vehicle_id, SUM(cost) AS spend",
    "  FROM service_records",
    "  WHERE serviced_on >= CURDATE() - INTERVAL 12 MONTH",
    "  GROUP BY vehicle_id",
    ") r ON r.vehicle_id = v.id",
    "SET v.in_service = 0",
    "WHERE v.model_year <= YEAR(CURDATE()) - 12",
    "  AND r.spend > 6000;",
    "",
};
static const char *const kMyBlock040[] = {
    "",
    "-- CI build stats: one row per pipeline run.",
    "CREATE TABLE ci_runs (",
    "  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,",
    "  repo VARCHAR(100) NOT NULL,",
    "  branch VARCHAR(200) NOT NULL,",
    "  commit_sha CHAR(40) NOT NULL,",
    "  trigger_kind ENUM('push','pull_request','schedule','manual') NOT NULL,",
    "  result ENUM('success','failure','cancelled','timeout') NULL,",
    "  queued_at DATETIME NOT NULL,",
    "  started_at DATETIME NULL,",
    "  finished_at DATETIME NULL,",
    "  duration_s INT GENERATED ALWAYS AS",
    "    (TIMESTAMPDIFF(SECOND, started_at, finished_at)) STORED,",
    "  runner_labels JSON NULL,",
    "  PRIMARY KEY (id),",
    "  KEY idx_ci_repo_branch (repo, branch, queued_at),",
    "  KEY idx_ci_result (result, finished_at)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;",
    "",
    "-- Median and p90 duration per repo on main, last 30 days.",
    "WITH ordered AS (",
    "  SELECT repo, duration_s,",
    "         PERCENT_RANK() OVER (PARTITION BY repo ORDER BY duration_s)",
    "           AS pr",
    "  FROM ci_runs",
    "  WHERE branch = 'main'",
    "    AND result = 'success'",
    "    AND finished_at >= NOW() - INTERVAL 30 DAY",
    ")",
    "SELECT",
    "  repo,",
    "  COUNT(*) AS runs,",
    "  MIN(IF(pr >= 0.5, duration_s, NULL)) AS p50_s,",
    "  MIN(IF(pr >= 0.9, duration_s, NULL)) AS p90_s,",
    "  MAX(duration_s) AS max_s",
    "FROM ordered",
    "GROUP BY repo",
    "ORDER BY p90_s DESC;",
    "",
};
static const char *const kMyBlock041[] = {
    "",
    "# Flaky tests: same commit, same test, both pass and fail.",
    "SELECT",
    "  tr.test_name,",
    "  r.repo,",
    "  COUNT(DISTINCT r.commit_sha) AS commits_affected,",
    "  SUM(tr.outcome = 'fail') AS fails,",
    "  SUM(tr.outcome = 'pass') AS passes,",
    "  MAX(r.finished_at) AS last_seen",
    "FROM test_results tr",
    "JOIN ci_runs r ON r.id = tr.run_id",
    "WHERE r.finished_at >= NOW() - INTERVAL 14 DAY",
    "  AND (r.commit_sha, tr.test_name) IN (",
    "    SELECT r2.commit_sha, tr2.test_name",
    "    FROM test_results tr2",
    "    JOIN ci_runs r2 ON r2.id = tr2.run_id",
    "    WHERE r2.finished_at >= NOW() - INTERVAL 14 DAY",
    "    GROUP BY r2.commit_sha, tr2.test_name",
    "    HAVING COUNT(DISTINCT tr2.outcome) > 1",
    "  )",
    "GROUP BY tr.test_name, r.repo",
    "ORDER BY commits_affected DESC, fails DESC",
    "LIMIT 30;",
    "",
    "-- Queue wait per runner label; labels are a JSON array of strings.",
    "SELECT",
    "  jt.label,",
    "  COUNT(*) AS runs,",
    "  ROUND(AVG(TIMESTAMPDIFF(SECOND, r.queued_at, r.started_at)), 0)",
    "    AS avg_wait_s",
    "FROM ci_runs r,",
    "     JSON_TABLE(r.runner_labels, '$[*]'",
    "       COLUMNS (label VARCHAR(40) PATH '$')) AS jt",
    "WHERE r.queued_at >= NOW() - INTERVAL 7 DAY",
    "  AND r.started_at IS NOT NULL",
    "GROUP BY jt.label",
    "ORDER BY avg_wait_s DESC;",
    "",
};
