static const char *const kMyBlock053[] = {
    "",
    "-- Employee directory: org chart via a recursive CTE.",
    "WITH RECURSIVE chain AS (",
    "  SELECT id, full_name, title, manager_id, 0 AS lvl,",
    "         CAST(full_name AS CHAR(2000)) AS trail",
    "  FROM employees",
    "  WHERE manager_id IS NULL",
    "  UNION ALL",
    "  SELECT e.id, e.full_name, e.title, e.manager_id, c.lvl + 1,",
    "         CONCAT(c.trail, ' > ', e.full_name)",
    "  FROM employees e",
    "  JOIN chain c ON e.manager_id = c.id",
    ")",
    "SELECT lvl, CONCAT(REPEAT('    ', lvl), full_name) AS name, title",
    "FROM chain",
    "ORDER BY trail;",
    "",
    "-- Span of control: direct and total reports for each manager.",
    "WITH RECURSIVE under AS (",
    "  SELECT manager_id AS boss, id AS report",
    "  FROM employees",
    "  WHERE manager_id IS NOT NULL",
    "  UNION ALL",
    "  SELECT u.boss, e.id",
    "  FROM under u",
    "  JOIN employees e ON e.manager_id = u.report",
    ")",
    "SELECT",
    "  m.full_name,",
    "  (SELECT COUNT(*) FROM employees d WHERE d.manager_id = m.id)",
    "    AS direct_reports,",
    "  COUNT(*) AS total_reports",
    "FROM under u",
    "JOIN employees m ON m.id = u.boss",
    "GROUP BY m.id, m.full_name",
    "ORDER BY total_reports DESC",
    "LIMIT 15;",
    "",
};
