static const char *const kMyBlock056[] = {
    "",
    "-- Cursor walk over overdue invoices to queue dunning emails.",
    "DELIMITER $$",
    "",
    "CREATE PROCEDURE queue_dunning()",
    "BEGIN",
    "  DECLARE v_done TINYINT DEFAULT 0;",
    "  DECLARE v_invoice_id INT UNSIGNED;",
    "  DECLARE v_account_id INT UNSIGNED;",
    "  DECLARE v_days_late INT;",
    "  DECLARE v_queued INT DEFAULT 0;",
    "",
    "  DECLARE cur_overdue CURSOR FOR",
    "    SELECT id, account_id, DATEDIFF(CURDATE(), due_on)",
    "    FROM invoices",
    "    WHERE status = 'open' AND due_on < CURDATE();",
    "",
    "  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;",
    "",
    "  OPEN cur_overdue;",
    "",
    "  read_loop: LOOP",
    "    FETCH cur_overdue INTO v_invoice_id, v_account_id, v_days_late;",
    "    IF v_done = 1 THEN",
    "      LEAVE read_loop;",
    "    END IF;",
    "",
    "    IF v_days_late IN (1, 7, 14, 30) THEN",
    "      INSERT IGNORE INTO email_queue (account_id, template, ref_id,",
    "                                      send_after)",
    "      VALUES (v_account_id,",
    "              CONCAT('dunning_d', v_days_late),",
    "              v_invoice_id,",
    "              NOW());",
    "      SET v_queued = v_queued + ROW_COUNT();",
    "    END IF;",
    "  END LOOP;",
    "",
    "  CLOSE cur_overdue;",
    "",
    "  SELECT v_queued AS emails_queued;",
    "END$$",
    "",
    "DELIMITER ;",
    "",
};
static const char *const kMyBlock057[] = {
    "",
    "# Invoices table and the aging report accounting asks for monthly.",
    "CREATE TABLE `invoices` (",
    "  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,",
    "  `account_id` INT UNSIGNED NOT NULL,",
    "  `number` VARCHAR(20) NOT NULL,",
    "  `issued_on` DATE NOT NULL,",
    "  `due_on` DATE NOT NULL,",
    "  `amount` DECIMAL(12,2) NOT NULL,",
    "  `paid_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00,",
    "  `status` ENUM('draft','open','paid','void') NOT NULL DEFAULT 'draft',",
    "  PRIMARY KEY (`id`),",
    "  UNIQUE KEY `uq_invoices_number` (`number`),",
    "  KEY `idx_invoices_status_due` (`status`, `due_on`)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;",
    "",
    "SELECT",
    "  a.name AS account,",
    "  SUM(IF(DATEDIFF(CURDATE(), i.due_on) <= 0,",
    "         i.amount - i.paid_amount, 0)) AS current_due,",
    "  SUM(IF(DATEDIFF(CURDATE(), i.due_on) BETWEEN 1 AND 30,",
    "         i.amount - i.paid_amount, 0)) AS d1_30,",
    "  SUM(IF(DATEDIFF(CURDATE(), i.due_on) BETWEEN 31 AND 60,",
    "         i.amount - i.paid_amount, 0)) AS d31_60,",
    "  SUM(IF(DATEDIFF(CURDATE(), i.due_on) BETWEEN 61 AND 90,",
    "         i.amount - i.paid_amount, 0)) AS d61_90,",
    "  SUM(IF(DATEDIFF(CURDATE(), i.due_on) > 90,",
    "         i.amount - i.paid_amount, 0)) AS d90_plus,",
    "  SUM(i.amount - i.paid_amount) AS total_open",
    "FROM `invoices` i",
    "JOIN accounts a ON a.id = i.account_id",
    "WHERE i.status = 'open'",
    "GROUP BY a.id, a.name",
    "HAVING total_open > 0",
    "ORDER BY d90_plus DESC, total_open DESC;",
    "",
};
