static const char *const kMyBlock065[] = {
    "",
    "-- Covers per service and average table turn, per restaurant.",
    "SELECT",
    "  r.restaurant_id,",
    "  DATE(r.reserved_for) AS day,",
    "  IF(HOUR(r.reserved_for) < 16, 'lunch', 'dinner') AS service,",
    "  SUM(r.party_size) AS covers,",
    "  COUNT(*) AS parties,",
    "  ROUND(AVG(TIMESTAMPDIFF(MINUTE, s.seated_at, s.left_at)), 0)",
    "    AS avg_turn_min",
    "FROM reservations r",
    "JOIN seatings s ON s.reservation_id = r.id",
    "WHERE r.status = 'done'",
    "  AND r.reserved_for >= CURDATE() - INTERVAL 14 DAY",
    "GROUP BY r.restaurant_id, day, service",
    "ORDER BY r.restaurant_id, day, service;",
    "",
    "-- Mark no-shows 20 minutes after the reservation time.",
    "UPDATE reservations",
    "SET status = 'no_show'",
    "WHERE status = 'booked'",
    "  AND reserved_for < NOW() - INTERVAL 20 MINUTE;",
    "",
    "-- Repeat guests by phone number, for the host stand notes.",
    "SELECT phone,",
    "       GROUP_CONCAT(DISTINCT guest_name ORDER BY guest_name",
    "                    SEPARATOR ' / ') AS names,",
    "       COUNT(*) AS visits,",
    "       MAX(reserved_for) AS last_visit",
    "FROM reservations",
    "WHERE status = 'done' AND phone IS NOT NULL",
    "GROUP BY phone",
    "HAVING visits >= 4",
    "ORDER BY visits DESC;",
    "",
};
