static const char *const kMyBlock067[] = {
    "",
    "# Heat waves: three or more consecutive days above 32C.",
    "WITH hot AS (",
    "  SELECT station_id, obs_date,",
    "         obs_date - INTERVAL ROW_NUMBER() OVER (",
    "           PARTITION BY station_id ORDER BY obs_date) DAY AS grp",
    "  FROM weather_daily",
    "  WHERE t_max > 32",
    ")",
    "SELECT",
    "  station_id,",
    "  MIN(obs_date) AS wave_start,",
    "  MAX(obs_date) AS wave_end,",
    "  COUNT(*) AS days",
    "FROM hot",
    "GROUP BY station_id, grp",
    "HAVING days >= 3",
    "ORDER BY days DESC, wave_start",
    "LIMIT 20;",
    "",
    "-- Day-over-day temperature swing using LAG.",
    "SELECT",
    "  obs_date,",
    "  t_max,",
    "  LAG(t_max) OVER (ORDER BY obs_date) AS prev_t_max,",
    "  t_max - LAG(t_max) OVER (ORDER BY obs_date) AS swing",
    "FROM weather_daily",
    "WHERE station_id = 'USW00094728'",
    "  AND obs_date >= CURDATE() - INTERVAL 60 DAY",
    "ORDER BY ABS(swing) DESC",
    "LIMIT 10;",
    "",
};
static const char *const kMyBlock068[] = {
    "",
    "-- Inventory movements and a perpetual stock valuation (FIFO-ish",
    "-- approximation using weighted average cost).",
    "CREATE TABLE stock_moves (",
    "  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,",
    "  sku VARCHAR(32) NOT NULL,",
    "  warehouse_id SMALLINT UNSIGNED NOT NULL,",
    "  qty INT NOT NULL,",
    "  unit_cost DECIMAL(10,4) NULL,",
    "  kind ENUM('receipt','sale','transfer_in','transfer_out','adjust')",
    "    NOT NULL,",
    "  ref_batch VARCHAR(20) NULL,",
    "  moved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,",
    "  PRIMARY KEY (id),",
    "  KEY idx_moves_sku (sku, warehouse_id, moved_at)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;",
    "",
    "SELECT",
    "  sku,",
    "  warehouse_id,",
    "  SUM(qty) AS on_hand,",
    "  ROUND(SUM(IF(kind = 'receipt', qty * unit_cost, 0))",
    "        / NULLIF(SUM(IF(kind = 'receipt', qty, 0)), 0), 4) AS avg_cost,",
    "  ROUND(SUM(qty)",
    "        * SUM(IF(kind = 'receipt', qty * unit_cost, 0))",
    "        / NULLIF(SUM(IF(kind = 'receipt', qty, 0)), 0), 2) AS value",
    "FROM stock_moves",
    "WHERE moved_at < CURDATE()",
    "GROUP BY sku, warehouse_id",
    "HAVING on_hand <> 0",
    "ORDER BY value DESC;",
    "",
    "-- Transfers must net to zero across warehouses for the same batch.",
    "SELECT ref_batch, SUM(qty) AS net",
    "FROM stock_moves",
    "WHERE kind IN ('transfer_in', 'transfer_out')",
    "  AND moved_at >= CURDATE() - INTERVAL 30 DAY",
    "GROUP BY ref_batch",
    "HAVING net <> 0;",
    "",
};
