static const char *const kMyBlock078[] = {
    "",
    "# Uptime checks: compute monthly availability per endpoint.",
    "SELECT",
    "  e.name,",
    "  DATE_FORMAT(c.checked_at, '%Y-%m') AS month,",
    "  COUNT(*) AS checks,",
    "  SUM(c.ok = 0) AS failures,",
    "  ROUND(100 * SUM(c.ok = 1) / COUNT(*), 3) AS availability_pct,",
    "  ROUND(AVG(IF(c.ok = 1, c.latency_ms, NULL)), 0) AS avg_latency_ms,",
    "  MAX(c.latency_ms) AS worst_latency_ms",
    "FROM uptime_checks c",
    "JOIN endpoints e ON e.id = c.endpoint_id",
    "WHERE c.checked_at >= DATE_FORMAT(NOW() - INTERVAL 2 MONTH, '%Y-%m-01')",
    "GROUP BY e.id, e.name, month",
    "ORDER BY e.name, month;",
    "",
    "-- Outage windows: consecutive failed checks collapsed into ranges.",
    "WITH marked AS (",
    "  SELECT endpoint_id, checked_at, ok,",
    "         SUM(ok) OVER (PARTITION BY endpoint_id ORDER BY checked_at)",
    "           AS grp",
    "  FROM uptime_checks",
    "  WHERE checked_at >= NOW() - INTERVAL 7 DAY",
    ")",
    "SELECT",
    "  endpoint_id,",
    "  MIN(checked_at) AS down_from,",
    "  MAX(checked_at) AS down_until,",
    "  TIMESTAMPDIFF(MINUTE, MIN(checked_at), MAX(checked_at)) + 1",
    "    AS minutes_down",
    "FROM marked",
    "WHERE ok = 0",
    "GROUP BY endpoint_id, grp",
    "HAVING COUNT(*) >= 2",
    "ORDER BY minutes_down DESC;",
    "",
};
static const char *const kMyBlock079[] = {
    "",
    "-- Feature flags with percentage rollout by a stable hash.",
    "CREATE TABLE feature_flags (",
    "  name VARCHAR(64) NOT NULL,",
    "  enabled TINYINT(1) NOT NULL DEFAULT 0,",
    "  rollout_pct TINYINT UNSIGNED NOT NULL DEFAULT 0,",
    "  allow_list JSON NULL,",
    "  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP",
    "    ON UPDATE CURRENT_TIMESTAMP,",
    "  PRIMARY KEY (name),",
    "  CONSTRAINT chk_rollout CHECK (rollout_pct <= 100)",
    ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;",
    "",
    "INSERT INTO feature_flags (name, enabled, rollout_pct, allow_list)",
    "VALUES ('new_checkout', 1, 25, JSON_ARRAY(1001, 1002, 7731))",
    "ON DUPLICATE KEY UPDATE",
    "  enabled = VALUES(enabled),",
    "  rollout_pct = VALUES(rollout_pct),",
    "  allow_list = VALUES(allow_list);",
    "",
    "-- Evaluate a flag for one account: allow list first, then bucket.",
    "SET @account := 48213;",
    "",
    "SELECT",
    "  f.name,",
    "  CASE",
    "    WHEN f.enabled = 0 THEN 0",
    "    WHEN @account MEMBER OF (f.allow_list) THEN 1",
    "    WHEN CRC32(CONCAT(f.name, ':', @account)) % 100 < f.rollout_pct",
    "      THEN 1",
    "    ELSE 0",
    "  END AS is_on",
    "FROM feature_flags f",
    "WHERE f.name = 'new_checkout';",
    "",
    "-- How many active accounts each flag currently reaches.",
    "SELECT f.name,",
    "       SUM(f.enabled = 1",
    "           AND CRC32(CONCAT(f.name, ':', a.id)) % 100 < f.rollout_pct)",
    "         AS accounts_on",
    "FROM feature_flags f",
    "CROSS JOIN accounts a",
    "WHERE a.status = 'active'",
    "GROUP BY f.name;",
    "",
};
