static const char *const kMyBlock093[] = {
    "",
    "-- Bike share docks: rebalancing needs from hourly snapshots.",
    "CREATE TABLE dock_snapshots (",
    "  station_id SMALLINT UNSIGNED NOT NULL,",
    "  taken_at DATETIME NOT NULL,",
    "  bikes TINYINT UNSIGNED NOT NULL,",
    "  docks_free TINYINT UNSIGNED NOT NULL,",
    "  PRIMARY KEY (station_id, taken_at)",
    ") ENGINE=InnoDB;",
    "",
    "-- Stations that ran empty or full most often on weekday mornings.",
    "SELECT",
    "  s.name,",
    "  SUM(d.bikes = 0) AS empty_hours,",
    "  SUM(d.docks_free = 0) AS full_hours,",
    "  ROUND(AVG(d.bikes), 1) AS avg_bikes",
    "FROM dock_snapshots d",
    "JOIN stations s ON s.id = d.station_id",
    "WHERE d.taken_at >= CURDATE() - INTERVAL 28 DAY",
    "  AND WEEKDAY(d.taken_at) < 5",
    "  AND HOUR(d.taken_at) BETWEEN 7 AND 9",
    "GROUP BY s.id, s.name",
    "HAVING empty_hours + full_hours > 10",
    "ORDER BY empty_hours + full_hours DESC;",
    "",
    "-- Net flow per station per hour of day: positive means bikes arrive.",
    "SELECT station_id, HOUR(taken_at) AS hr,",
    "       ROUND(AVG(bikes - prev_bikes), 2) AS avg_net_flow",
    "FROM (",
    "  SELECT station_id, taken_at, bikes,",
    "         LAG(bikes) OVER (PARTITION BY station_id ORDER BY taken_at)",
    "           AS prev_bikes",
    "  FROM dock_snapshots",
    "  WHERE taken_at >= CURDATE() - INTERVAL 14 DAY",
    ") x",
    "WHERE prev_bikes IS NOT NULL",
    "GROUP BY station_id, hr",
    "ORDER BY station_id, hr;",
    "",
};
static const char *const kMyBlock094[] = {
    "",
    "-- Archive old orders into a compressed table, a month at a time.",
    "CREATE TABLE IF NOT EXISTS orders_archive LIKE orders;",
    "",
    "ALTER TABLE orders_archive ROW_FORMAT=COMPRESSED;",
    "",
    "DELIMITER $$",
    "",
    "CREATE PROCEDURE archive_orders_month(IN p_month DATE)",
    "BEGIN",
    "  DECLARE v_from DATETIME DEFAULT DATE_FORMAT(p_month, '%Y-%m-01');",
    "  DECLARE v_to DATETIME DEFAULT v_from + INTERVAL 1 MONTH;",
    "  DECLARE v_moved INT DEFAULT 1;",
    "  DECLARE v_total INT DEFAULT 0;",
    "",
    "  IF v_to > CURDATE() - INTERVAL 18 MONTH THEN",
    "    SIGNAL SQLSTATE '45000'",
    "      SET MESSAGE_TEXT = 'Only months older than 18 months may move';",
    "  END IF;",
    "",
    "  -- Small batches keep undo logs short and replicas current.",
    "  WHILE v_moved > 0 DO",
    "    START TRANSACTION;",
    "",
    "    INSERT INTO orders_archive",
    "    SELECT * FROM orders",
    "    WHERE placed_at >= v_from AND placed_at < v_to",
    "      AND status IN ('shipped', 'cancelled', 'refunded')",
    "    ORDER BY id",
    "    LIMIT 2000;",
    "",
    "    SET v_moved = ROW_COUNT();",
    "    SET v_total = v_total + v_moved;",
    "",
    "    DELETE o FROM orders o",
    "    JOIN orders_archive a ON a.id = o.id",
    "    WHERE o.placed_at >= v_from AND o.placed_at < v_to;",
    "",
    "    COMMIT;",
    "  END WHILE;",
    "",
    "  SELECT v_total AS orders_archived;",
    "END$$",
    "",
    "DELIMITER ;",
    "",
    "CALL archive_orders_month('2023-03-01');",
    "",
};

