static const char *const kOraBlock002[] = {
    "",
    "-- Overdue invoices bucketed by age, newest debtors first.",
    "SELECT i.invoice_no,",
    "       o.customer_id,",
    "       i.amount_net + i.amount_tax                   AS amount_gross,",
    "       TRUNC(SYSDATE) - i.due_on                     AS days_late,",
    "       CASE",
    "         WHEN TRUNC(SYSDATE) - i.due_on <= 30 THEN '0-30'",
    "         WHEN TRUNC(SYSDATE) - i.due_on <= 60 THEN '31-60'",
    "         WHEN TRUNC(SYSDATE) - i.due_on <= 90 THEN '61-90'",
    "         ELSE '90+'",
    "       END                                           AS age_bucket,",
    "       TO_CHAR(i.due_on, 'YYYY-MM-DD')               AS due_label",
    "  FROM invoices i",
    "  JOIN orders o",
    "    ON o.order_id = i.order_id",
    " WHERE i.paid_on IS NULL",
    "   AND i.due_on < TRUNC(SYSDATE)",
    " ORDER BY days_late DESC, amount_gross DESC",
    " FETCH FIRST 50 ROWS ONLY;",
    "",
};
static const char *const kOraBlock003[] = {
    "",
    "-- Org chart walk from the top, with the reporting path for each node.",
    "SELECT LEVEL                                        AS depth,",
    "       LPAD(' ', (LEVEL - 1) * 2) || e.full_name    AS indented_name,",
    "       e.job_title,",
    "       SYS_CONNECT_BY_PATH(e.emp_code, '/')         AS chain,",
    "       CONNECT_BY_ISLEAF                            AS is_leaf",
    "  FROM employees e",
    " START WITH e.manager_id IS NULL CONNECT BY PRIOR e.emp_id = e.manager_id",
    " ORDER SIBLINGS BY e.full_name;",
    "",
    "-- Head count under every manager, counting all indirect reports too.",
    "SELECT m.emp_code,",
    "       m.full_name,",
    "       (SELECT COUNT(*) - 1",
    "          FROM employees x",
    "         START WITH x.emp_id = m.emp_id CONNECT BY",
    "               PRIOR x.emp_id = x.manager_id)",
    "                                                     AS total_reports",
    "  FROM employees m",
    " WHERE EXISTS (SELECT 1 FROM employees s WHERE s.manager_id = m.emp_id)",
    " ORDER BY total_reports DESC;",
    "",
};
