static const char *const kOraBlock007[] = {
    "",
    "CREATE OR REPLACE TRIGGER bookings_ai_trg",
    "AFTER INSERT ON bookings",
    "FOR EACH ROW",
    "DECLARE",
    "  l_left NUMBER;",
    "BEGIN",
    "  UPDATE flights",
    "     SET seats_sold = seats_sold + :NEW.seat_count",
    "   WHERE flight_id = :NEW.flight_id",
    "  RETURNING seats_total - seats_sold INTO l_left;",
    "",
    "  IF SQL%ROWCOUNT = 0 THEN",
    "    RAISE_APPLICATION_ERROR(-20010, 'Unknown flight ' || :NEW.flight_id);",
    "  END IF;",
    "",
    "  -- The check constraint catches oversell, but a clear message helps.",
    "  IF l_left < 0 THEN",
    "    RAISE_APPLICATION_ERROR(-20011, 'Flight is oversold');",
    "  END IF;",
    "END;",
    "/",
    "",
};
static const char *const kOraBlock008[] = {
    "",
    "-- Load factor per route for the last quarter, with share of capacity.",
    "SELECT f.origin_iata || '-' || f.dest_iata              AS route,",
    "       COUNT(*)                                         AS legs,",
    "       SUM(f.seats_sold)                                AS pax,",
    "       ROUND(SUM(f.seats_sold) / SUM(f.seats_total) * 100, 1)",
    "                                                        AS load_pct,",
    "       ROUND(RATIO_TO_REPORT(SUM(f.seats_total)) OVER () * 100, 2)",
    "                                                        AS capacity_share",
    "  FROM flights f",
    " WHERE f.departs_at >= ADD_MONTHS(TRUNC(SYSDATE, 'Q'), -3)",
    "   AND f.departs_at <  TRUNC(SYSDATE, 'Q')",
    " GROUP BY f.origin_iata, f.dest_iata",
    "HAVING COUNT(*) >= 10",
    " ORDER BY load_pct DESC;",
    "",
};
static const char *const kOraBlock009[] = {
    "",
    "DECLARE",
    "  l_member   library_members%ROWTYPE;",
    "  l_overdue  NUMBER;",
    "  l_fee      NUMBER(8,2) := 0;",
    "BEGIN",
    "  SELECT *",
    "    INTO l_member",
    "    FROM library_members",
    "   WHERE member_no = :p_member_no;",
    "",
    "  SELECT COUNT(*),",
    "         NVL(SUM(GREATEST(TRUNC(SYSDATE) - due_on, 0) * 0.25), 0)",
    "    INTO l_overdue, l_fee",
    "    FROM loans",
    "   WHERE member_id = l_member.member_id",
    "     AND returned_on IS NULL",
    "     AND due_on < TRUNC(SYSDATE);",
    "",
    "  IF l_overdue = 0 THEN",
    "    DBMS_OUTPUT.PUT_LINE(l_member.display_name || ': all clear');",
    "  ELSIF l_fee < 5 THEN",
    "    DBMS_OUTPUT.PUT_LINE(l_member.display_name || ': reminder only');",
    "  ELSE",
    "    UPDATE library_members",
    "       SET status = 'SUSPENDED',",
    "           status_changed_on = SYSDATE",
    "     WHERE member_id = l_member.member_id;",
    "    DBMS_OUTPUT.PUT_LINE('suspended, fee ' || TO_CHAR(l_fee, '990.00'));",
    "  END IF;",
    "EXCEPTION",
    "  WHEN NO_DATA_FOUND THEN",
    "    DBMS_OUTPUT.PUT_LINE('no member ' || :p_member_no);",
    "  WHEN OTHERS THEN",
    "    DBMS_OUTPUT.PUT_LINE('failed: ' || SQLERRM);",
    "    RAISE;",
    "END;",
    "/",
    "",
};
