static const char *const kOraBlock024[] = {
    "",
    "-- League standings computed from match results.",
    "WITH results AS (",
    "  SELECT home_team_id AS team_id,",
    "         CASE WHEN home_goals > away_goals THEN 3",
    "              WHEN home_goals = away_goals THEN 1",
    "              ELSE 0 END            AS points,",
    "         home_goals                 AS goals_for,",
    "         away_goals                 AS goals_against",
    "    FROM matches",
    "   WHERE season = :p_season AND played = 'Y'",
    "  UNION ALL",
    "  SELECT away_team_id,",
    "         CASE WHEN away_goals > home_goals THEN 3",
    "              WHEN away_goals = home_goals THEN 1",
    "              ELSE 0 END,",
    "         away_goals,",
    "         home_goals",
    "    FROM matches",
    "   WHERE season = :p_season AND played = 'Y'",
    ")",
    "SELECT DENSE_RANK() OVER (ORDER BY SUM(r.points) DESC,",
    "                          SUM(r.goals_for - r.goals_against) DESC)",
    "                                                  AS place,",
    "       t.team_name,",
    "       COUNT(*)                                   AS played,",
    "       SUM(r.points)                              AS points,",
    "       SUM(r.goals_for) || ':' || SUM(r.goals_against) AS goals",
    "  FROM results r",
    "  JOIN teams t ON t.team_id = r.team_id",
    " GROUP BY t.team_name",
    " ORDER BY place, t.team_name;",
    "",
};
