static const char *const kOraBlock028[] = {
    "",
    "CREATE OR REPLACE TRIGGER service_records_biu_trg",
    "BEFORE INSERT OR UPDATE ON service_records",
    "FOR EACH ROW",
    "DECLARE",
    "  l_odo vehicles.odometer_km%TYPE;",
    "BEGIN",
    "  SELECT odometer_km INTO l_odo",
    "    FROM vehicles",
    "   WHERE vehicle_id = :NEW.vehicle_id;",
    "",
    "  IF :NEW.odometer_km > l_odo THEN",
    "    -- A service visit is a trusted reading; move the vehicle forward.",
    "    UPDATE vehicles",
    "       SET odometer_km = :NEW.odometer_km",
    "     WHERE vehicle_id = :NEW.vehicle_id;",
    "  ELSIF :NEW.odometer_km < l_odo - 500 THEN",
    "    RAISE_APPLICATION_ERROR(-20040, 'Odometer reading goes backwards');",
    "  END IF;",
    "",
    "  IF INSERTING THEN",
    "    :NEW.created_at := SYSTIMESTAMP;",
    "  ELSIF UPDATING AND :OLD.serviced_on <> :NEW.serviced_on THEN",
    "    :NEW.serviced_on := :OLD.serviced_on;",
    "  END IF;",
    "END;",
    "/",
    "",
};
static const char *const kOraBlock029[] = {
    "",
    "-- Scratch space for the pricing run; rows vanish at commit.",
    "CREATE GLOBAL TEMPORARY TABLE gtt_price_calc (",
    "  sku           VARCHAR2(30 CHAR),",
    "  base_price    NUMBER(12,2),",
    "  discount_pct  NUMBER(5,2),",
    "  final_price   NUMBER(12,2)",
    ") ON COMMIT DELETE ROWS;",
    "",
    "INSERT INTO gtt_price_calc (sku, base_price, discount_pct)",
    "SELECT p.sku,",
    "       p.list_price,",
    "       NVL(MAX(d.discount_pct), 0)",
    "  FROM products p",
    "  LEFT JOIN discounts d",
    "    ON d.category_id = p.category_id",
    "   AND TRUNC(SYSDATE) BETWEEN d.starts_on AND d.ends_on",
    " GROUP BY p.sku, p.list_price;",
    "",
    "UPDATE gtt_price_calc",
    "   SET final_price = ROUND(base_price * (1 - discount_pct / 100), 2);",
    "",
    "MERGE INTO product_prices t",
    "USING gtt_price_calc s",
    "ON (t.sku = s.sku AND t.price_date = TRUNC(SYSDATE))",
    "WHEN MATCHED THEN UPDATE SET t.price = s.final_price",
    "WHEN NOT MATCHED THEN INSERT (sku, price_date, price)",
    "  VALUES (s.sku, TRUNC(SYSDATE), s.final_price);",
    "",
    "COMMIT;",
    "",
};
