static const char *const kOraBlock037[] = {
    "",
    "-- Drop telemetry partitions older than the retention window.",
    "DECLARE",
    "  CURSOR c_parts IS",
    "    SELECT partition_name, high_value",
    "      FROM user_tab_partitions",
    "     WHERE table_name = 'SENSOR_READINGS'",
    "     ORDER BY partition_position;",
    "",
    "  l_high   TIMESTAMP WITH TIME ZONE;",
    "  l_cutoff TIMESTAMP WITH TIME ZONE := SYSTIMESTAMP - INTERVAL '180' DAY;",
    "  l_count  PLS_INTEGER := 0;",
    "BEGIN",
    "  FOR p IN c_parts LOOP",
    "    -- high_value is a LONG holding an expression; evaluate it.",
    "    EXECUTE IMMEDIATE 'SELECT ' || p.high_value || ' FROM DUAL'",
    "      INTO l_high;",
    "",
    "    IF l_high < l_cutoff AND p.partition_name <> 'P_START' THEN",
    "      EXECUTE IMMEDIATE 'ALTER TABLE sensor_readings DROP PARTITION '",
    "        || p.partition_name || ' UPDATE INDEXES';",
    "      l_count := l_count + 1;",
    "    END IF;",
    "  END LOOP;",
    "",
    "  write_job_log('telemetry_retention', 'INFO',",
    "                'dropped partitions: ' || l_count);",
    "EXCEPTION",
    "  WHEN OTHERS THEN",
    "    write_job_log('telemetry_retention', 'ERROR', SQLERRM);",
    "    RAISE;",
    "END;",
    "/",
    "",
};
