static const char *const kOraBlock057[] = {
    "",
    "-- Close claims that have been fully paid and idle for ninety days.",
    "DECLARE",
    "  CURSOR c_idle IS",
    "    SELECT c.claim_id, c.claim_no",
    "      FROM claims c",
    "     WHERE c.status = 'OPEN'",
    "       AND NOT EXISTS (SELECT 1 FROM claim_history h",
    "                        WHERE h.claim_id = c.claim_id",
    "                          AND h.changed_at > SYSDATE - 90)",
    "       AND (SELECT NVL(SUM(reserve_delta - paid_delta), 0)",
    "              FROM claim_history h",
    "             WHERE h.claim_id = c.claim_id) = 0;",
    "  l_closed PLS_INTEGER := 0;",
    "BEGIN",
    "  FOR r IN c_idle LOOP",
    "    UPDATE claims",
    "       SET status = 'CLOSED', closed_on = TRUNC(SYSDATE)",
    "     WHERE claim_id = r.claim_id;",
    "",
    "    INSERT INTO claim_history (claim_id, status, reserve_delta,",
    "                               paid_delta, changed_at)",
    "    VALUES (r.claim_id, 'CLOSED', 0, 0, SYSTIMESTAMP);",
    "    l_closed := l_closed + 1;",
    "  END LOOP;",
    "  COMMIT;",
    "  write_job_log('claims_autoclose', 'INFO', 'closed ' || l_closed);",
    "END;",
    "/",
    "",
};
