static const char *const kOraBlock062[] = {
    "",
    "-- Parking sessions: compute fees on exit using a tariff table.",
    "CREATE OR REPLACE FUNCTION parking_fee (",
    "  p_zone_code IN VARCHAR2,",
    "  p_entered   IN DATE,",
    "  p_exited    IN DATE",
    ") RETURN NUMBER IS",
    "  l_minutes   NUMBER;",
    "  l_fee       NUMBER(8,2) := 0;",
    "  l_daily_cap tariffs.daily_cap%TYPE;",
    "  l_per_hour  tariffs.per_hour%TYPE;",
    "  l_free_min  tariffs.free_minutes%TYPE;",
    "BEGIN",
    "  SELECT per_hour, daily_cap, free_minutes",
    "    INTO l_per_hour, l_daily_cap, l_free_min",
    "    FROM tariffs",
    "   WHERE zone_code = p_zone_code",
    "     AND p_entered BETWEEN valid_from AND NVL(valid_to, p_entered);",
    "",
    "  l_minutes := ROUND((p_exited - p_entered) * 1440);",
    "  IF l_minutes <= l_free_min THEN",
    "    RETURN 0;",
    "  END IF;",
    "",
    "  -- Whole days at the cap, remainder by started hour, capped again.",
    "  l_fee := TRUNC(l_minutes / 1440) * l_daily_cap",
    "         + LEAST(CEIL(MOD(l_minutes, 1440) / 60) * l_per_hour,",
    "                 l_daily_cap);",
    "  RETURN l_fee;",
    "EXCEPTION",
    "  WHEN NO_DATA_FOUND THEN",
    "    RAISE_APPLICATION_ERROR(-20080, 'No tariff for zone ' || p_zone_code);",
    "END parking_fee;",
    "/",
    "",
};
