static const char *const kOraBlock078[] = {
    "",
    "-- Reject leave requests that overlap an already approved absence.",
    "CREATE OR REPLACE TRIGGER leave_requests_biu_trg",
    "BEFORE INSERT OR UPDATE ON leave_requests",
    "FOR EACH ROW",
    "DECLARE",
    "  l_overlap NUMBER;",
    "  PRAGMA AUTONOMOUS_TRANSACTION;",
    "BEGIN",
    "  IF :NEW.end_on < :NEW.start_on THEN",
    "    RAISE_APPLICATION_ERROR(-20120, 'Leave ends before it starts');",
    "  END IF;",
    "",
    "  -- Autonomous so the check can read the table being changed.",
    "  SELECT COUNT(*)",
    "    INTO l_overlap",
    "    FROM leave_requests",
    "   WHERE emp_id = :NEW.emp_id",
    "     AND request_id <> NVL(:NEW.request_id, -1)",
    "     AND status = 'APPROVED'",
    "     AND start_on <= :NEW.end_on",
    "     AND end_on   >= :NEW.start_on;",
    "",
    "  IF l_overlap > 0 THEN",
    "    RAISE_APPLICATION_ERROR(-20121, 'Overlaps an approved absence');",
    "  END IF;",
    "",
    "  :NEW.days_taken := (:NEW.end_on - :NEW.start_on) + 1;",
    "END;",
    "/",
    "",
};
static const char *const kOraBlock079[] = {
    "",
    "-- Fuel efficiency per vehicle model; outliers may need inspection.",
    "SELECT v.model_name,",
    "       COUNT(DISTINCT v.vehicle_id)                         AS vehicles,",
    "       ROUND(SUM(f.litres) / NULLIF(SUM(f.km_since_last), 0) * 100, 2)",
    "                                                            AS l_per_100km,",
    "       ROUND(AVG(f.price_per_litre), 3)                     AS avg_price",
    "  FROM fuel_purchases f",
    "  JOIN vehicles v ON v.vehicle_id = f.vehicle_id",
    " WHERE f.purchased_on >= ADD_MONTHS(TRUNC(SYSDATE), -3)",
    " GROUP BY ROLLUP (v.model_name)",
    " ORDER BY l_per_100km DESC NULLS LAST;",
    "",
    "-- Vehicles more than 20 percent worse than their own model average.",
    "WITH per_vehicle AS (",
    "  SELECT v.vehicle_id, v.plate_no, v.model_name,",
    "         SUM(f.litres) / NULLIF(SUM(f.km_since_last), 0) * 100 AS l100",
    "    FROM fuel_purchases f",
    "    JOIN vehicles v ON v.vehicle_id = f.vehicle_id",
    "   WHERE f.purchased_on >= ADD_MONTHS(TRUNC(SYSDATE), -3)",
    "   GROUP BY v.vehicle_id, v.plate_no, v.model_name",
    ")",
    "SELECT plate_no, model_name, ROUND(l100, 2) AS l100,",
    "       ROUND(AVG(l100) OVER (PARTITION BY model_name), 2) AS model_avg",
    "  FROM per_vehicle",
    " WHERE l100 > 1.2 * (SELECT AVG(p2.l100) FROM per_vehicle p2",
    "                      WHERE p2.model_name = per_vehicle.model_name);",
    "",
};
