static const char *const kOraBlock093[] = {
    "",
    "-- Credit notes reverse part of an invoice; the trigger keeps totals sane.",
    "CREATE TABLE credit_notes (",
    "  credit_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,",
    "  invoice_id    NUMBER(12)       NOT NULL,",
    "  amount        NUMBER(12,2)     NOT NULL,",
    "  reason        VARCHAR2(200 CHAR) NOT NULL,",
    "  issued_on     DATE             DEFAULT TRUNC(SYSDATE) NOT NULL,",
    "  CONSTRAINT credit_notes_pk PRIMARY KEY (credit_id),",
    "  CONSTRAINT credit_notes_inv_fk FOREIGN KEY (invoice_id)",
    "    REFERENCES invoices (invoice_id),",
    "  CONSTRAINT credit_notes_amt_ck CHECK (amount > 0)",
    ");",
    "",
    "CREATE OR REPLACE TRIGGER credit_notes_bi_trg",
    "BEFORE INSERT ON credit_notes",
    "FOR EACH ROW",
    "DECLARE",
    "  l_gross     NUMBER(12,2);",
    "  l_credited  NUMBER(12,2);",
    "BEGIN",
    "  SELECT amount_net + amount_tax INTO l_gross",
    "    FROM invoices WHERE invoice_id = :NEW.invoice_id;",
    "",
    "  SELECT NVL(SUM(amount), 0) INTO l_credited",
    "    FROM credit_notes WHERE invoice_id = :NEW.invoice_id;",
    "",
    "  IF l_credited + :NEW.amount > l_gross THEN",
    "    RAISE_APPLICATION_ERROR(-20130, 'Credit exceeds invoice total');",
    "  END IF;",
    "END;",
    "/",
    "",
};
