static const char *const kOraBlock098[] = {
    "",
    "-- Order line totals feed the header; recompute when lines change.",
    "CREATE OR REPLACE TRIGGER order_lines_aiud_trg",
    "AFTER INSERT OR UPDATE OR DELETE ON order_lines",
    "FOR EACH ROW",
    "DECLARE",
    "  l_delta NUMBER(12,2);",
    "BEGIN",
    "  l_delta := NVL(:NEW.qty * :NEW.unit_price, 0)",
    "           - NVL(:OLD.qty * :OLD.unit_price, 0);",
    "",
    "  IF l_delta <> 0 THEN",
    "    UPDATE orders",
    "       SET order_total = order_total + l_delta",
    "     WHERE order_id = NVL(:NEW.order_id, :OLD.order_id);",
    "  END IF;",
    "",
    "  IF UPDATING('ORDER_ID') THEN",
    "    RAISE_APPLICATION_ERROR(-20140, 'Lines cannot move between orders');",
    "  END IF;",
    "END;",
    "/",
    "",
};
