static const char *const kOraBlock102[] = {
    "",
    "-- Close a work order and roll the labour and parts cost onto the asset.",
    "CREATE OR REPLACE PROCEDURE close_work_order (p_wo_id IN NUMBER) IS",
    "  l_wo      work_orders%ROWTYPE;",
    "  l_labour  NUMBER(12,2);",
    "  l_parts   NUMBER(12,2);",
    "BEGIN",
    "  SELECT * INTO l_wo FROM work_orders WHERE wo_id = p_wo_id FOR UPDATE;",
    "",
    "  IF l_wo.status = 'CLOSED' THEN",
    "    RETURN;",
    "  END IF;",
    "",
    "  SELECT NVL(SUM(hours * rate), 0) INTO l_labour",
    "    FROM wo_labour WHERE wo_id = p_wo_id;",
    "",
    "  SELECT NVL(SUM(qty * unit_cost), 0) INTO l_parts",
    "    FROM wo_parts WHERE wo_id = p_wo_id;",
    "",
    "  UPDATE work_orders",
    "     SET status      = 'CLOSED',",
    "         closed_at   = SYSDATE,",
    "         total_cost  = l_labour + l_parts",
    "   WHERE wo_id = p_wo_id;",
    "",
    "  UPDATE assets",
    "     SET lifetime_cost   = NVL(lifetime_cost, 0) + l_labour + l_parts,",
    "         last_serviced   = TRUNC(SYSDATE)",
    "   WHERE asset_id = l_wo.asset_id;",
    "EXCEPTION",
    "  WHEN NO_DATA_FOUND THEN",
    "    RAISE_APPLICATION_ERROR(-20150, 'Work order ' || p_wo_id || ' missing');",
    "END close_work_order;",
    "/",
    "",
};
