static const char *const kOraBlock106[] = {
    "",
    "CREATE OR REPLACE PROCEDURE record_match_result (",
    "  p_match_id   IN NUMBER,",
    "  p_home_goals IN NUMBER,",
    "  p_away_goals IN NUMBER",
    ") IS",
    "  l_match  bracket_matches%ROWTYPE;",
    "  l_winner NUMBER;",
    "BEGIN",
    "  IF p_home_goals = p_away_goals THEN",
    "    RAISE_APPLICATION_ERROR(-20160, 'Knockout matches need a winner');",
    "  END IF;",
    "",
    "  SELECT * INTO l_match FROM bracket_matches",
    "   WHERE match_id = p_match_id FOR UPDATE;",
    "",
    "  l_winner := CASE WHEN p_home_goals > p_away_goals",
    "                   THEN l_match.home_team_id",
    "                   ELSE l_match.away_team_id END;",
    "",
    "  UPDATE bracket_matches",
    "     SET home_goals = p_home_goals,",
    "         away_goals = p_away_goals,",
    "         winner_id  = l_winner",
    "   WHERE match_id = p_match_id;",
    "",
    "  -- Fill the first free slot in the next round.",
    "  UPDATE bracket_matches",
    "     SET home_team_id = NVL(home_team_id, l_winner),",
    "         away_team_id = CASE WHEN home_team_id IS NOT NULL",
    "                             THEN l_winner ELSE away_team_id END",
    "   WHERE match_id = l_match.next_match_id;",
    "END record_match_result;",
    "/",
    "",
};
